-- FAR: Delete Employee Benefit Plans questions recreated by stale orchestrator run
-- These were generated by batches 96-98 which used an outdated generation plan
-- Employee Benefit Plans is not on the AICPA 2026 FAR blueprint

BEGIN;

DO $DEL$
DECLARE
  far_id INT;
  deleted INT;
BEGIN
  SELECT id INTO far_id FROM sections WHERE code = 'far';

  DELETE FROM questions
    WHERE section_id = far_id
      AND topic = 'Employee Benefit Plans';

  GET DIAGNOSTICS deleted = ROW_COUNT;
  RAISE NOTICE 'Deleted % orphaned Employee Benefit Plans questions from FAR', deleted;
END;
$DEL$;

COMMIT;
